package com.lebzlon.measurementtracker.service;
import com.lebzlon.measurementtracker.dto.Dtos.*; import java.util.List;
@RestController class AuthController{ private final AuthService s; AuthController(AuthService s){this.s=s;} @PostMapping("/auth/register") AuthResponse register(@Valid @RequestBody RegisterRequest r){return s.register(r);} @PostMapping("/auth/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);} }
@RestController class UserController{ private final UserService s; UserController(UserService s){this.s=s;} @GetMapping("/users/me") UserResponse me(){return s.me();}}
@RestController class MeterController{ private final MeterService s; MeterController(MeterService s){this.s=s;} @PostMapping("/meters") MeterResponse create(@Valid @RequestBody MeterRequest r){return s.create(r);} @GetMapping("/meters") List<MeterResponse> list(){return s.list();} @GetMapping("/meters/{id}") MeterResponse one(@PathVariable Long id){return s.one(id);} @PutMapping("/meters/{id}") MeterResponse update(@PathVariable Long id,@Valid @RequestBody MeterRequest r){return s.update(id,r);} @DeleteMapping("/meters/{id}") void del(@PathVariable Long id){s.delete(id);} }
@RestController class ReadingController{ private final ReadingService s; ReadingController(ReadingService s){this.s=s;} @PostMapping("/readings/manual") ReadingResponse create(@Valid @RequestBody ManualReadingRequest r){return s.addManual(r);} @GetMapping("/readings") List<ReadingResponse> list(){return s.list();} @GetMapping("/readings/{id}") ReadingResponse one(@PathVariable Long id){return s.one(id);} @GetMapping("/readings/meter/{meterId}") List<ReadingResponse> byMeter(@PathVariable Long meterId){return s.byMeter(meterId);} @GetMapping("/readings/history") List<ReadingResponse> h(@RequestParam Long meterId,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant to){return s.history(meterId,from,to);} }
@RestController class OcrController{ private final OcrTaskService s; OcrController(OcrTaskService s){this.s=s;} @PostMapping("/ocr/tasks") OcrTaskResponse create(@RequestParam Long meterId,@RequestParam Instant timestamp,@RequestPart MultipartFile file) throws IOException {return s.create(meterId,timestamp,file);} @GetMapping("/ocr/tasks") List<OcrTaskResponse> list(){return s.list();} @GetMapping("/ocr/tasks/{id}") OcrTaskResponse one(@PathVariable Long id){return s.one(id);} }
@Controller class FrontendController { @GetMapping({"/","/login"}) String login(){return "login";} @GetMapping("/register") String register(){return "register";} @GetMapping("/dashboard") String dashboard(){return "dashboard";} @GetMapping("/meters-page") String meters(){return "meters";} @GetMapping("/meter-create") String meterCreate(){return "meter-create";} @GetMapping("/manual-reading") String manual(){return "manual-reading";} @GetMapping("/ocr-upload") String ocr(){return "ocr-upload";} @GetMapping("/ocr-status") String ocrStatus(){return "ocr-status";} @GetMapping("/readings-history") String readings(){return "readings-history";} }
